function ldiff(a,b){var n=a.length,m=b.length,d=[],i,j;for(i=0;i<=n;i++)d.push(new Array(m+1).fill(0));for(i=n-1;i>=0;i--)for(j=m-1;j>=0;j--)d[i][j]=a[i]===b[j]?d[i+1][j+1]+1:Math.max(d[i+1][j],d[i][j+1]);var o=[];i=0;j=0;while(i<n&&j<m){if(a[i]===b[j]){o.push('  '+a[i]);i++;j++}else if(d[i+1][j]>=d[i][j+1]){o.push('- '+a[i]);i++}else{o.push('+ '+b[j]);j++}}while(i<n)o.push('- '+a[i++]);while(j<m)o.push('+ '+b[j++]);return o.join('\n')}
tx('text','🆚','Text Diff Checker','Compare two texts line by line. Put ===== on its own line between them.',function(s){var p=s.split(/\n={3,}\n/);if(p.length<2)throw new Error('Put ===== on a separate line between the two texts');return ldiff(p[0].split('\n'),p[1].split('\n'))+'\n\n( - removed   + added )'},'First text\nHello world\n=====\nSecond text\nHello world');
var STW='the a an and or of to in on for is are was were it this that with as by at be from have has had not but you your we our they their i he she his her its so if will can'.split(' ');
tx('text','📰','Quick Text Summarizer','Picks the most important sentences from a long text.',function(s){var ss=(s.match(/[^.!?\n]+[.!?]*/g)||[]).map(function(x){return x.trim()}).filter(function(x){return x.length>25});if(ss.length<4)return s.trim()||'Paste a longer text (at least 4 sentences).';var f={};wd(s).forEach(function(w){if(STW.indexOf(w)<0&&w.length>2)f[w]=(f[w]||0)+1});var sc=ss.map(function(x,i){var w=wd(x),t=0;w.forEach(function(q){t+=f[q]||0});return{i:i,s:x,v:t/Math.sqrt(w.length||1)}}),k=Math.max(2,Math.round(ss.length*.3));return sc.sort(function(a,b){return b.v-a.v}).slice(0,k).sort(function(a,b){return a.i-b.i}).map(function(x){return x.s}).join(' ')},'Paste a long article or notes (English)...');
